15	fn main() -> ExitCode {
16	    // args_os (not args): on Unix a key file path may contain bytes that are
17	    // not valid UTF-8, and those are legitimate on-disk names we must accept
18	    // verbatim rather than panic on.
19	    let args: Vec<OsString> = env::args_os().skip(1).collect();
20	
21	    match args.first().map(OsString::as_os_str) {
22	        Some(a) if a == "--version" && args.len() == 1 => {
23	            println!("{VERSION_STRING}");
24	            ExitCode::SUCCESS
25	        }
26	        Some(a) if a == "keygen" => run_keygen(&args[1..]),
27	        _ => {
28	            print_usage();
29	            ExitCode::from(2)
30	        }
31	    }
32	}
33	
34	fn print_usage() {
35	    eprintln!("Usage: wrapfile --version");
36	    eprintln!("       wrapfile keygen <KEY_FILE>");
37	}
