39	fn run_keygen(args: &[OsString]) -> ExitCode {
40	    // A leading "--" marks the end of options, allowing a path that starts
41	    // with '-' to be passed (e.g. `wrapfile keygen -- -weird-name`).
42	    let (args, options_ended): (&[OsString], bool) = match args {
43	        [first, rest @ ..] if first == "--" => (rest, true),
44	        _ => (args, false),
45	    };
46	    let path: &OsStr = match args {
47	        [] => {
48	            eprintln!("wrapfile keygen: missing key file path");
49	            print_usage();
50	            return ExitCode::from(2);
51	        }
52	        [p] if options_ended || !starts_with_dash(p) => p,
53	        [p] => {
54	            // render_path already adds the surrounding double quotes when
55	            // the option text needs escaping, so no extra quotes go here.
56	            eprintln!("wrapfile keygen: unknown option {}", render_path(p));
57	            print_usage();
58	            return ExitCode::from(2);
59	        }
60	        _ => {
61	            eprintln!("wrapfile keygen: expected exactly one argument (key file path)");
62	            print_usage();
63	            return ExitCode::from(2);
64	        }
65	    };
66	
67	    match generate_key_file(path) {
68	        Ok(()) => {
69	            println!("Key saved to {}", render_path(path));
70	            ExitCode::SUCCESS
71	        }
72	        Err(e) => {
73	            eprintln!("wrapfile keygen: {e}");
74	            ExitCode::from(1)
75	        }
76	    }
77	}
