511	#[cfg(unix)]
512	fn ensure_owner_only_mode(fd: RawFd) -> std::io::Result<()> {
513	    // The mode passed to open() is masked by the process umask, so a strict
514	    // umask (e.g. 0777) can strip the owner read/write bits, and some
515	    // filesystems may adjust or refuse the requested mode. fchmod on the
516	    // open fd is not affected by the umask: force exactly 0600 and then
517	    // fstat to confirm the filesystem actually stores those bits. This
518	    // runs before any key byte is written, so a file that cannot meet the
519	    // requirement never receives secret data.
520	    if unsafe { libc::fchmod(fd, 0o600) } != 0 {
521	        let e = std::io::Error::last_os_error();
522	        return Err(std::io::Error::new(
523	            e.kind(),
524	            format!(
525	                "cannot set key file permissions to 0600: {e} \
526	                 (filesystem does not support the required permissions)"
527	            ),
528	        ));
529	    }
530	
531	    let mut st: libc::stat = unsafe { std::mem::zeroed() };
532	    if unsafe { libc::fstat(fd, &mut st) } != 0 {
533	        // Without a fresh stat result the actual on-disk mode cannot be
534	        // confirmed, so the requirement cannot be met -- say so explicitly
535	        // rather than surface a bare errno string.
536	        let e = std::io::Error::last_os_error();
537	        return Err(std::io::Error::new(
538	            e.kind(),
539	            format!("cannot verify key file permissions are 0600: {e}"),
540	        ));
541	    }
542	
543	    // Exactly owner read/write, no group or other permissions of any kind.
544	    // This rejects 0400/0200/0000 (owner bits missing under a strict umask)
545	    // as well as any mode carrying group/other bits.
546	    if st.st_mode & 0o7777 != 0o600 {
547	        return Err(std::io::Error::new(
548	            std::io::ErrorKind::Other,
549	            format!(
550	                "cannot guarantee key file permissions 0600: \
551	                 filesystem reports mode 0{:04o}",
