561	    // Caller has already run ensure_owner_only_mode: the inode carries
562	    // exactly 0600 before the first secret byte reaches it. Failures are
563	    // labelled with the stage so the user can tell an unfinished write
564	    // apart from a permission or sync problem.
565	    write_all(fd, key).map_err(|e| {
566	        std::io::Error::new(e.kind(), format!("could not write key file: {e}"))
567	    })?;
