399	        let tmp = Tmp::new("fchmod-fail");
400	        let key = tmp.child("key");
401	        let sibling = Sentinel::file(&tmp.path, "sibling", b"do-not-touch", 0o644);
402	        let parent_mode_before = mode_of(&tmp.path);
