543	    let run2 = run_keygen(&key, 0o022, Some(&so), &[], Some(&trace2));
544	    assert_key_file_ok(&key, &run2);
545	    sibling.assert_untouched();
546	}
547	
548	#[test]
549	fn version_and_argument_handling_unchanged() {
550	    // --version
551	    let v = run_version();
552	    assert_eq!(v.rc, 0);
553	    assert_eq!(String::from_utf8_lossy(&v.out), "wrapfile 0.1.0\n");
554	    assert!(v.err.is_empty());
555	
556	    let tmp = Tmp::new("cli");
557	
558	    // missing path / extra args / unknown option all exit 2 and create files.
559	    let cases: &[&[&str]] = &[
560	        &["keygen"],
561	        &["keygen", "a", "b"],
562	        &["keygen", "--bogus"],
563	    ];
564	    for args in cases {
565	        let before: Vec<String> = fs::read_dir(&tmp.path)
566	            .unwrap()
567	            .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
568	            .collect();
569	        let run = run_args(args);
570	        assert_eq!(run.rc, 2, "args {args:?} should exit 2");
571	        assert!(
572	            String::from_utf8_lossy(&run.err).contains("Usage"),
573	            "usage must be printed on stderr for {args:?}"
574	        );
575	        let after: Vec<String> = fs::read_dir(&tmp.path)
576	            .unwrap()
577	            .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
578	            .collect();
579	        assert_eq!(before, after, "argument errors must not create files ({args:?})");
580	    }
581	
582	    // Totally unknown invocation -> 2 as well.
583	    let run = run_args(&["frobnicate"]);
584	    assert_eq!(run.rc, 2);
585	}
586	
587	#[test]
588	fn fchmod_rejection_with_unlink_refused_reports_both_and_warns_of_residue() {
589	    let Some(so) = permfail_so() else {
590	        eprintln!("skipping: permfail shim not available on this target");
591	        return;
592	    };
593	
594	    let tmp = Tmp::new("fchmod-fail-unlink-refused");
595	    let key = tmp.child("key");
596	    let sibling = Sentinel::file(&tmp.path, "sibling", b"keep-me", 0o600);
597	    let parent_mode_before = mode_of(&tmp.path);
598	    let trace = prepare_trace(&tmp.path, "trace.log");
599	
600	    // The filesystem refuses to set the required mode, and the system then
601	    // refuses to remove this run's (empty) file. The command must report
602	    // both the permission problem and the unfinished cleanup.
603	    let run = run_keygen(
604	        &key,
605	        0o022,
606	        Some(&so),
607	        &[
608	            ("WRAPFILE_TEST_FAIL_FCHMOD", "1"),
609	            ("WRAPFILE_TEST_FAIL_UNLINK", "1"),
610	        ],
611	        Some(&trace),
612	    );
613	
614	    let events = parse_trace(&trace);
615	    assert!(
616	        events
617	            .iter()
618	            .any(|e| e.kind == "FCHMOD" && e.ret() == Some(-1)),
619	        "the fchmod failure must have been injected"
620	    );
621	    assert!(
622	        events
623	            .iter()
624	            .any(|e| e.kind == "UNLINK" && e.get("errno") == Some("EACCES")),
625	        "the refused cleanup must have been injected"
626	    );
627	    // No key byte was ever written: the residue is a mere empty file.
628	    assert!(
629	        events.iter().all(|e| e.kind != "WRITE" && e.kind != "FIRST_WRITE"),
630	        "no key byte may be written when the permissions cannot be guaranteed"
631	    );
632	
633	    assert_eq!(run.rc, 1, "a failed save with refused cleanup must exit 1");
634	    assert!(
635	        run.out.is_empty(),
636	        "no success message on failure, got {}",
637	        String::from_utf8_lossy(&run.out)
638	    );
639	    let stderr = String::from_utf8_lossy(&run.err);
640	    assert!(
641	        stderr.contains(&key.display().to_string()),
642	        "stderr should name the target path, got: {stderr}"
643	    );
644	    // The original permission problem is still reported...
645	    assert!(
646	        stderr.contains("0600") || stderr.to_lowercase().contains("permission"),
647	        "stderr must keep the permission problem, got: {stderr}"
648	    );
649	    // ...the cleanup failure is reported too...
650	    assert!(
651	        stderr.contains("cleanup"),
652	        "stderr must report the failed cleanup, got: {stderr}"
653	    );
654	    // ...and the user is warned that this run's file may remain -- even
655	    // though it is only an empty file, it must not be mistaken for a key.
656	    assert!(
657	        stderr.contains("may still be present"),
658	        "stderr must warn that this run's file may remain, got: {stderr}"
659	    );
660	
661	    // The refused removal means this run's empty file really is still at
662	    // the target; nothing was stashed under another name.
663	    assert!(
664	        key.exists(),
665	        "with unlink refused, this run's file remains at the target"
666	    );
667	    assert_eq!(
668	        fs::read(&key).unwrap().len(),
669	        0,
670	        "the residue must be the empty file exactly as the failed run left it"
671	    );
672	    let mut entries: Vec<String> = fs::read_dir(&tmp.path)
673	        .unwrap()
674	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
675	        .collect();
676	    entries.sort();
677	    assert_eq!(
678	        entries,
679	        vec!["key".to_string(), "sibling".to_string(), "trace.log".to_string()],
680	        "no renamed copy or other leftover may appear"
681	    );
682	    sibling.assert_untouched();
683	    assert_eq!(
684	        mode_of(&tmp.path),
685	        parent_mode_before,
686	        "parent directory permissions must never be loosened to force cleanup"
687	    );
688	
689	    // Remove the residue manually; a fault-free retry then succeeds.
690	    fs::remove_file(&key).unwrap();
691	    let trace2 = prepare_trace(&tmp.path, "trace2.log");
692	    let run2 = run_keygen(&key, 0o022, Some(&so), &[], Some(&trace2));
693	    assert_key_file_ok(&key, &run2);
694	    sibling.assert_untouched();
695	}
