238	/// Run the keylife observer around `wrapfile keygen <key>` with the given
239	/// LD_PRELOAD libraries and extra environment.
240	fn observe(
241	    observer: &Path,
242	    bin: &Path,
243	    scenario: &str,
244	    key: &Path,
245	    preloads: &[PathBuf],
246	    extra_env: &[(&str, &str)],
247	    trace: &Path,
248	) -> Observation {
249	    let dir = key.parent().unwrap();
250	    let out_cap = dir.join("guest.stdout");
251	    let err_cap = dir.join("guest.stderr");
252	    for f in [&out_cap, &err_cap] {
253	        let _ = fs::remove_file(f);
254	    }
255	
256	    let preload = preloads
257	        .iter()
258	        .map(|p| p.display().to_string())
259	        .collect::<Vec<_>>()
260	        .join(":");
261	
262	    let output = Command::new(observer)
263	        .arg(scenario)
264	        .arg(&out_cap)
265	        .arg(&err_cap)
266	        .arg("--")
267	        .arg(bin)
268	        .arg("keygen")
269	        .arg(key)
270	        .env("LD_PRELOAD", preload)
271	        .env("WRAPFILE_TEST_TRACE_FILE", trace)
272	        .envs(extra_env.iter().copied())
273	        .output()
274	        .expect("run keylife observer");
275	
276	    Observation {
277	        rc: output.status.code().unwrap_or(-1),
278	        observer_err: String::from_utf8_lossy(&output.stderr).into_owned(),
279	        events: parse_events(&output.stdout),
280	        fail: fail_reason(&output.stdout),
281	    }
282	}
