284	fn guest_captured(key: &Path) -> (Vec<u8>, Vec<u8>) {
285	    let dir = key.parent().unwrap();
286	    let out = fs::read(dir.join("guest.stdout")).unwrap_or_default();
287	    let err = fs::read(dir.join("guest.stderr")).unwrap_or_default();
