356	
357	/// The random bytes the key fill received, reconstructed from the trace.
358	fn key_fill_bytes(events: &[GrEvent]) -> Vec<u8> {
359	    let start = events
360	        .iter()
361	        .rposition(|e| e.req == KEY_LEN)
362	        .expect("keygen must draw the 32 key bytes");
363	    events[start..]
364	        .iter()
365	        .filter(|e| e.ret > 0)
366	        .flat_map(|e| (0..e.ret as usize).map(move |i| pattern_byte(e.base + i)))
367	        .collect()
368	}
