370	/// Global draw index at which keygen's own 32-byte fill starts: the `base`
371	/// of its first (req=32) call. Bytes before that are the process runtime's
372	/// own startup consumption and vary across environments, so a fail-after-N
373	/// scenario is calibrated from this instead of a hard-coded N.
374	fn key_fill_base(events: &[GrEvent]) -> usize {
375	    events
376	        .iter()
377	        .rposition(|e| e.req == KEY_LEN)
378	        .map(|i| events[i].base)
379	        .expect("keygen must draw the 32 key bytes")
380	}
