582	fn partial_random_failure_wipes_fragment_and_entire_buffer(
583	    sup: &Support,
584	    bin: &Path,
585	    profile: &str,
586	) {
587	    let tmp = Tmp::new(&format!("randfail-{profile}"));
588	    let key = tmp.child("key");
589	    let (sib, sib_bytes, sib_mode) = make_sibling(&tmp.path);
590	    let parent_before = mode_of(&tmp.path);
591	    let trace = tmp.child("trace.log");
592	    fs::File::create(&trace).unwrap();
593	    fs::set_permissions(&trace, fs::Permissions::from_mode(0o644)).unwrap();
594	
595	    // Calibrate where keygen's own 32-byte fill starts in the shim's global
596	    // draw counter. The process runtime draws some bytes of its own first,
597	    // and that amount must not be hard-coded; it also depends on the fault
598	    // semantics (a PARTIAL limit truncates the runtime's own call while a
599	    // FAIL_AFTER cutoff does not), so the probe uses the *same* FAIL_AFTER
600	    // mechanism with a quota far beyond anything the process will draw: the
601	    // guest completes normally and its trace records the fill's base. The
602	    // real fault run then cuts the source a fixed number of bytes into the
603	    // fill.
604	    const TARGET_FRAGMENT: usize = 13;
605	    let cal_dir = Tmp::new(&format!("randfail-cal-{profile}"));
606	    let cal_key = cal_dir.child("cal");
607	    let cal_trace = cal_dir.child("trace.log");
608	    fs::File::create(&cal_trace).unwrap();
609	    fs::set_permissions(&cal_trace, fs::Permissions::from_mode(0o644)).unwrap();
610	    let cal = observe(
611	        &sup.observer,
612	        bin,
613	        "success",
614	        &cal_key,
615	        &[sup.randtrap.clone()],
616	        &[("WRAPFILE_TEST_GETRANDOM_FAIL_AFTER", "100000")],
617	        &cal_trace,
618	    );
619	    if !observer_ran(&cal) {
620	        return;
621	    }
622	    if !trap_armed(&cal_trace) {
623	        eprintln!("skipping: randtrap seccomp trap did not arm here");
624	        return;
625	    }
626	    assert_eq!(cal.rc, 0, "calibration run must succeed");
627	    let fill_base = key_fill_base(&getrandom_events(&cal_trace));
628	    let fail_after = fill_base + TARGET_FRAGMENT;
629	
630	    let fail_after_env = fail_after.to_string();
631	    let obs = observe(
632	        &sup.observer,
633	        bin,
634	        "randfail",
635	        &key,
636	        &[sup.randtrap.clone()],
637	        &[("WRAPFILE_TEST_GETRANDOM_FAIL_AFTER", fail_after_env.as_str())],
638	        &trace,
639	    );
640	    if !observer_ran(&obs) {
641	        return;
642	    }
643	    assert!(trap_armed(&trace), "fault run must have the trap armed");
644	    assert_eq!(
645	        obs.rc, 0,
646	        "[{profile}] observer must confirm the wipe, got FAIL: {:?}",
647	        obs.fail.clone()
648	    );
649	
650	    // The scenario really delivered a strict prefix of the key and then
651	    // failed the draw -- corroborated both by the observer and by the
652	    // shim's own trace.
653	    let rf = obs.first("RANDOM_FAILED").expect("RANDOM_FAILED event");
654	    let held = rf.usize("held").expect("held=");
655	    let sentinel = rf.usize("sentinel").expect("sentinel=");
656	    assert!(held > 0 && held < KEY_LEN, "fragment must be 1..31 bytes");
657	    assert_eq!(
658	        held, TARGET_FRAGMENT,
659	        "calibrated cutoff must land {TARGET_FRAGMENT} bytes into the fill"
660	    );
661	    assert_eq!(sentinel, KEY_LEN - held);
662	
663	    // The shim trace independently shows a strict partial delivery followed
664	    // by an unrecoverable error inside the key fill.
665	    let trace_events = getrandom_events(&trace);
666	    let fill_start = trace_events
667	        .iter()
668	        .rposition(|e| e.req == KEY_LEN)
669	        .expect("fault trace must contain the 32-byte fill request");
670	    let fill_calls = &trace_events[fill_start..];
671	    let traced_held: usize = fill_calls.iter().filter(|e| e.ret > 0).map(|e| e.ret as usize).sum();
672	    assert!(
673	        traced_held > 0 && traced_held < KEY_LEN,
674	        "trace must show a strict partial fill, got {traced_held} bytes"
675	    );
676	    assert_eq!(traced_held, held, "observer and trace agree on fragment size");
677	    assert!(
678	        fill_calls.iter().any(|e| e.ret < 0),
679	        "the fill must have ended with an injected failure"
680	    );
681	
682	    // The wipe covers the delivered fragment *and* the never-delivered
683	    // tail (proven by the planted sentinel being erased), before the error
684	    // report and before the operation returned.
685	    let wiped = obs.first("WIPED").expect("WIPED event");
686	    assert_eq!(wiped.usize("held"), Some(held));
687	    assert_eq!(wiped.usize("sentinel"), Some(sentinel));
688	    let i_wiped = obs.index("WIPED").unwrap();
689	    let i_output = obs
690	        .index("OUTPUT_AFTER_WIPE")
691	        .expect("the error report must be observed after the wipe");
692	    assert!(i_wiped < i_output, "wipe must precede the failure report");
693	    assert_eq!(
694	        obs.first("GUEST_EXIT").and_then(|e| e.i64("rc")),
695	        Some(1)
696	    );
697	
698	    // Public failure behavior: no key file, no zero-padded stand-in,
699	    // exit 1, empty stdout, stderr explains the random-source failure and
700	    // names nothing secret; existing files and the parent are untouched.
701	    assert!(!key.exists(), "no key file may be created on a partial draw");
702	    let (out, err) = guest_captured(&key);
703	    assert!(out.is_empty(), "stdout must be empty on failure");
704	    let err_text = String::from_utf8_lossy(&err);
705	    assert!(
706	        err_text.contains("cryptographic random source unavailable"),
707	        "stderr must explain the random-source failure: {err_text}"
708	    );
709	    // The delivered fragment must not appear in the report, raw or hex.
710	    let events = getrandom_events(&trace);
711	    let drawn: Vec<u8> = events
712	        .iter()
713	        .rposition(|e| e.req == KEY_LEN)
714	        .map(|s| {
715	            events[s..]
716	                .iter()
717	                .filter(|e| e.ret > 0)
718	                .flat_map(|e| (0..e.ret as usize).map(move |i| pattern_byte(e.base + i)))
719	                .collect()
720	        })
721	        .unwrap_or_default();
722	    assert_eq!(drawn.len(), held);
723	    assert!(
724	        !contains_slice(&out, &drawn) && !contains_slice(&err, &drawn),
725	        "the delivered fragment must never appear raw on stdout/stderr"
726	    );
727	    let hex: String = drawn.iter().map(|b| format!("{b:02x}")).collect();
728	    assert!(!err_text.contains(&hex), "fragment must not appear hex-encoded");
729	
730	    assert_sentinel_untouched(&sib, &sib_bytes, sib_mode);
731	    assert_eq!(mode_of(&tmp.path), parent_before, "parent mode must survive");
732	}
