734	fn write_failure_after_full_key_still_wipes_the_full_key(
735	    sup: &Support,
736	    bin: &Path,
737	    profile: &str,
738	) {
739	    let tmp = Tmp::new(&format!("writefail-{profile}"));
740	    let key = tmp.child("key");
741	    let (sib, sib_bytes, sib_mode) = make_sibling(&tmp.path);
742	    let parent_before = mode_of(&tmp.path);
743	    let trace = tmp.child("trace.log");
744	    fs::File::create(&trace).unwrap();
745	    fs::set_permissions(&trace, fs::Permissions::from_mode(0o644)).unwrap();
746	
747	    // Deterministic full key, then the permfail shim accepts only 4 bytes
748	    // per write and fails with EIO once 10 bytes have landed: part of the
749	    // key is on disk, the save aborts, the file is unlinked.
750	    let obs = observe(
751	        &sup.observer,
752	        bin,
753	        "writefail",
754	        &key,
755	        &[sup.randtrap.clone(), sup.permfail.clone()],
756	        &[
757	            ("WRAPFILE_TEST_GETRANDOM_PARTIAL", "8"),
758	            ("WRAPFILE_TEST_PARTIAL_WRITE", "4"),
759	            ("WRAPFILE_TEST_FAIL_WRITE_AFTER", "10"),
760	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
761	        ],
762	        &trace,
763	    );
764	    if !observer_ran(&obs) {
765	        return;
766	    }
767	    if !trap_armed(&trace) {
768	        eprintln!("skipping: randtrap seccomp trap did not arm here");
769	        return;
770	    }
771	    assert_eq!(
772	        obs.rc, 0,
773	        "[{profile}] observer must confirm the wipe, got FAIL: {:?}",
774	        obs.fail.clone()
775	    );
776	
777	    // The full, non-zero key was delivered and still held live across the
778	    // key writes, the abort's unlink, and the abort's close.
779	    let secret = obs.secret();
780	    assert_eq!(secret.len(), KEY_LEN);
781	    assert!(secret.iter().all(|&b| b != 0));
782	    assert!(!obs.named("WRITE_BORROWS").is_empty());
783	    assert!(obs.first("WRITE_FAILED").is_some(), "abort unlink must see the full key");
784	    assert!(obs.first("ABORT_UNLINK").is_some());
785	    assert!(obs.first("ABORT_CLOSE_STILL_HELD").is_some());
786	
787	    // The whole full key was wiped before the error report / return.
788	    let i_wiped = obs.index("WIPED").expect("WIPED event");
789	    let wiped = obs.first("WIPED").unwrap();
790	    assert_eq!(wiped.usize("held"), Some(KEY_LEN));
791	    assert_eq!(wiped.usize("sentinel"), Some(0));
792	    assert!(
793	        obs.index("ABORT_CLOSE_STILL_HELD").unwrap() < i_wiped,
794	        "wipe must follow the abort close"
795	    );
796	    assert!(
797	        i_wiped < obs.index("OUTPUT_AFTER_WIPE").unwrap(),
798	        "wipe must precede the failure report"
799	    );
800	    assert_eq!(
801	        obs.first("GUEST_EXIT").and_then(|e| e.i64("rc")),
802	        Some(1)
803	    );
804	
805	    // Public failure behavior: no leftover file, exit 1, empty stdout,
806	    // stderr names the write failure and the target path.
807	    assert!(!key.exists(), "the aborted file must be cleaned up");
808	    let (out, err) = guest_captured(&key);
809	    assert!(out.is_empty(), "no success message on failure");
810	    let err_text = String::from_utf8_lossy(&err);
811	    assert!(
812	        err_text.contains("could not write key file"),
813	        "stderr must explain the write failure: {err_text}"
814	    );
815	    assert!(
816	        err_text.contains(&key.display().to_string()),
817	        "stderr must name the target: {err_text}"
818	    );
819	    // The full key must not leak, raw or hex.
820	    assert!(
821	        !err.windows(KEY_LEN).any(|w| w == secret.as_slice()),
822	        "full key must not appear raw on stderr"
823	    );
824	    let hex: String = secret.iter().map(|b| format!("{b:02x}")).collect();
825	    assert!(!err_text.contains(&hex), "full key must not appear hex-encoded");
826	
827	    assert_sentinel_untouched(&sib, &sib_bytes, sib_mode);
828	    assert_eq!(mode_of(&tmp.path), parent_before, "parent mode must survive");
829	}
