901	fn close_failure_after_full_save_still_wipes_the_full_key(
902	    sup: &Support,
903	    bin: &Path,
904	    profile: &str,
905	) {
906	    let tmp = Tmp::new(&format!("closefail-{profile}"));
907	    let key = tmp.child("key");
908	    let (sib, sib_bytes, sib_mode) = make_sibling(&tmp.path);
909	    let parent_before = mode_of(&tmp.path);
910	    let trace = tmp.child("trace.log");
911	    fs::File::create(&trace).unwrap();
912	    fs::set_permissions(&trace, fs::Permissions::from_mode(0o644)).unwrap();
913	
914	    // Deterministic full key; all 32 bytes are written and fsynced, then
915	    // the permfail shim really releases the descriptor but reports EIO for
916	    // the close. The file on disk briefly looks complete -- the save must
917	    // still fail, the file must be removed, and the in-memory key must be
918	    // wiped before the failure is reported.
919	    let obs = observe(
920	        &sup.observer,
921	        bin,
922	        "closefail",
923	        &key,
924	        &[sup.randtrap.clone(), sup.permfail.clone()],
925	        &[
926	            ("WRAPFILE_TEST_GETRANDOM_PARTIAL", "8"),
927	            ("WRAPFILE_TEST_FAIL_CLOSE", "1"),
928	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
929	        ],
930	        &trace,
931	    );
932	    if !observer_ran(&obs) {
933	        return;
934	    }
935	    if !trap_armed(&trace) {
936	        eprintln!("skipping: randtrap seccomp trap did not arm here");
937	        return;
938	    }
939	    let secret = assert_closefail_wipe(&obs, &trace, profile);
940	
941	    // abort_save's cleanup ran while the full key was still held; the wipe
942	    // came only afterwards.
943	    assert!(
944	        obs.first("ABORT_UNLINK").is_some(),
945	        "the cleanup unlink must still see the full key"
946	    );
947	    assert!(
948	        obs.index("ABORT_UNLINK").unwrap() < obs.index("WIPED").unwrap(),
949	        "wipe must follow the abort cleanup"
950	    );
951	
952	    // Public failure behavior: exit 1, empty stdout, stderr says the
953	    // failure happened while closing the key file and names the target;
954	    // this run's file is gone; the key leaks nowhere.
955	    assert!(!key.exists(), "the file from the failed close must be removed");
956	    let (out, err) = guest_captured(&key);
957	    assert!(out.is_empty(), "no success message on failure");
958	    let err_text = String::from_utf8_lossy(&err);
959	    assert!(
960	        err_text.contains("closing the key file"),
