962	    );
963	    assert!(
964	        err_text.contains(&key.display().to_string()),
965	        "stderr must name the target: {err_text}"
966	    );
967	    assert_key_not_leaked(&out, &err, &secret);
968	
969	    assert_sentinel_untouched(&sib, &sib_bytes, sib_mode);
970	    assert_eq!(mode_of(&tmp.path), parent_before, "parent mode must survive");
971	}
