#[test]
fn chmod_failure_after_full_key_zeroes_before_returning_under_both_profiles() {
    let Some(sup) = support() else {
        eprintln!("skipping: keylife/randtrap/permfail support unavailable");
        return;
    };
    let sup = &sup;
    let run = |bin: &Path, profile: &str| {
        // #permission-failure-zeroing
        // The fchmod(0600) on the freshly created key file is refused
        // (EPERM) after the full 32-byte key was drawn but before any key
        // byte is written: the in-memory key must still be wiped before
        // completely before the failure is reported.
        let _ = (bin, profile);
    };
    let _ = run;
    let _ = sup;
}

